cssCode:
.stack-wrap {
  padding: 50px 20px 200px 20px;
  display: flex;
  flex-direction: column;
  gap: 30px;
}
.stack-card {
  position: sticky;
  height: 250px;
  width: 100%;
  max-width: 350px;
  margin: 0 auto;
  border-radius: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 30px;
  font-weight: bold;
  color: #fff;
  font-family: sans-serif;
  box-shadow: 0 -10px 30px rgba(0,0,0,0.5);
  transform-origin: top center;
  transition: transform 0.2s linear;
}
.card-a { background: #ff007f; top: 50px; }
.card-b { background: #6c63ff; top: 70px; }
.card-c { background: #00ffcc; color: #000; top: 90px; }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#0f0f15;';

const wrap = document.createElement('div');
wrap.className = 'stack-wrap';

const cards = [
  { cls: 'card-a', txt: 'CARD ONE' },
  { cls: 'card-b', txt: 'CARD TWO' },
  { cls: 'card-c', txt: 'CARD THREE' }
];

const cardEls = [];
cards.forEach(data => {
  const div = document.createElement('div');
  div.className = `stack-card ${data.cls}`;
  div.innerText = data.txt;
  cardEls.push(div);
  wrap.appendChild(div);
});

c.appendChild(wrap);

c.addEventListener('scroll', () => {
  cardEls.forEach((el, index) => {
    const rect = el.getBoundingClientRect();
    const stickyTop = parseInt(window.getComputedStyle(el).top);

    // જો કાર્ડ પોતાની સ્ટીકી પોઝિશન પર પહોંચી જાય, તો 3D સ્કેલ ડાઉન થાય
    if (rect.top <= stickyTop) {
      const scaleAmount = Math.max(0.8, 1 - Math.abs(rect.top - stickyTop) * 0.001);
      el.style.transform = `scale(${scaleAmount})`;
    } else {
      el.style.transform = `scale(1)`;
    }
  });
});
